// Base64 copies of the adjacent Pillow-generated image fixtures for workerd (no filesystem I/O).
const images: Record<string, string> = {
  'metadata.png':
    '',
  'metadata.webp':
    '',
  'gps.jpg':
    '',
  'animated.gif':
    'R0lGODlhAgACAIEAAP8AAAAAAAAAAAAAACH/C05FVFNDQVBFMi4wAwEAAAAh/hBwcml2YXRlLWxvY2F0aW9uACH5BAAFAAAALAAAAAACAAIAAAgGAAEIBBAQACH5BAEFAAEALAAAAAACAAIAgQAA/wAAAAAAAAAAAAgGAAEIBBAQACH/C1BSSVZBVEVBUFAxEHByaXZhdGUtbG9jYXRpb24AOw==',
};
export function customFixture(name: string) {
  return Uint8Array.from(atob(images[name]!), (c) => c.charCodeAt(0));
}
